from pathlib import Path
root=Path(__file__).resolve().parents[1]/'dist'
origin='https://bus-date-navi.pages.dev'
nav='<header class="site-header"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">☾</span><span>日付まちがい防止ナビ<small>NIGHT BUS · DATE CHECK</small></span></a><nav aria-label="メイン"><a href="/guide.html">日付の読み方</a><span class="free">無料・登録不要</span></nav></header>'
footer='<footer><a class="footer-brand" href="/">日付まちがい防止ナビ</a><nav aria-label="サイト情報"><a href="/guide.html">使い方・よくある質問</a><a href="/about.html">運営・お問い合わせ</a><a href="/privacy.html">プライバシー</a><a href="/terms.html">利用上の注意</a></nav><small>F計画SP ｜ 日本国内の移動・日本時間（JST）に対応</small></footer>'
def page(file,title,desc,content,script=False):
    url=origin+('/' if file=='index.html' else '/'+file.removesuffix('.html'))
    head=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><meta name="theme-color" content="#162f50"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:locale" content="ja_JP"><meta name="twitter:card" content="summary"><meta name="google-adsense-account" content="ca-pub-2422278081062267"><link rel="icon" href="/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">'''
    (root/file).write_text(head+('<script type="module" src="/app.mjs"></script>' if script else '')+'</head><body><a class="skip" href="#main">本文へ移動</a>'+nav+content+footer+'</body></html>')

def field(id,label,placeholder,hint):
    return f'<div class="field"><label for="{id}">{label}</label><input id="{id}" name="{id}" type="text" inputmode="text" placeholder="{placeholder}" maxlength="24" aria-describedby="{id}-hint" autocomplete="off" spellcheck="false"><small id="{id}-hint">{hint}</small></div>'

home='''<main id="main"><section class="hero"><div><p class="eyebrow">夜行バス・ライブ遠征の、出発前に。</p><h1>出発する夜を、<br><span>もう間違えない。</span></h1><p class="hero-lead">「7日の24:20」って、いつ乗るの？<br>予約画面の日付と時刻から、<strong>カレンダー上の日時</strong>を確認できます。</p><div class="hero-tags"><span>24時・25時表記に対応</span><span>予定は端末内で処理</span></div></div><div class="night-art" aria-hidden="true"><div class="moon"></div><span class="star s1">✦</span><span class="star s2">·</span><span class="star s3">✧</span><div class="bus"><div class="windows"><i></i><i></i><i></i><i></i></div><div class="bus-stripe"></div><span>NIGHT JOURNEY</span><b class="wheel w1"></b><b class="wheel w2"></b></div><div class="road"></div><div class="art-caption">日付の境目に、小さな安心を。</div></div></section>
<div class="important-intro"><span aria-hidden="true">ⓘ</span><p><strong>予約の確認をお手伝いするツールです。</strong> 入力した表記を変換します。予約日・運行日は会社によって異なるため、最後は予約元で確認してください。</p></div>
<div class="workspace"><section class="panel input-panel" aria-labelledby="input-title"><div class="section-heading"><span class="step">01</span><h2 id="input-title">予約画面の表記を入力</h2></div><p class="muted">購入手続きした日ではなく、予約詳細にある出発日です。</p><form id="check-form" novalidate><fieldset><legend>出発日時 <span class="required">必須</span></legend>'''
home+=field('departureDate','表示されている出発日','例：2026/11/07','年/月/日、または年-月-日。全角でも入力できます。')
home+=field('departureTime','表示されている出発時刻','例：24:20','00:00〜29:59。「翌日」の注記があるときは予約元で確認。')
home+='''</fieldset><div class="sample-line"><button id="sample" class="text-button" type="button">入力例を試す：11/7 24:20</button><span id="sample-notice" hidden>入力例です。ご自身の予約に置き換えてください。</span></div><details class="optional"><summary>到着・ホテルの日程も確認する <span>任意</span></summary><p class="muted">こちらはカレンダー上の日付・00〜23時表記で入力します。分からない場合は空欄で構いません。</p><fieldset><legend>バスの到着予定</legend><div class="optional-grid">'''
home+=field('arrivalDate','到着予定日','例：2026/11/08','実際のカレンダー日付')+field('arrivalTime','到着予定時刻','例：07:00','00:00〜23:59')
home+='</div></fieldset><fieldset><legend>ホテルのチェックイン予定</legend><div class="optional-grid">'
home+=field('hotelDate','チェックイン予定日','例：2026/11/08','予約した宿泊日の確認も必要')+field('hotelTime','チェックイン予定時刻','例：15:00','00:00〜23:59')
home+='''</div></fieldset></details><div id="form-error" class="error" role="alert" hidden></div><button class="primary" type="submit">乗車日時を確認する <span aria-hidden="true">→</span></button><button class="reset" id="clear-input" type="button">入力をすべて消す</button><p class="local-note">予約番号・名前の入力は不要。<br>このフォームの予定は外部へ送信しません。</p></form><noscript><p class="error">計算にはJavaScriptを有効にしてください。日付の読み方は下のガイドで確認できます。</p></noscript></section>
<section class="panel result-panel" aria-label="確認結果"><div class="section-heading"><span class="step light">02</span><h2>カレンダー上の日時を確認</h2></div><div id="empty-result" class="empty-result"><div class="calendar-icon" aria-hidden="true"><span>DATE CHECK</span><b>？</b></div><h3>何日の、何時に乗る？</h3><p>日付と時刻を入力すると、<br>ここに確認結果が表示されます。</p><div class="example"><small>たとえば</small><span>11月7日 <b>24:20</b> 発</span><span class="example-arrow">↓</span><strong>11月8日 午前0時20分</strong><small>7日の夜から準備する目安</small></div></div>
<div id="result" hidden><p class="result-input">予約画面の入力 <strong id="input-summary"></strong></p><div class="actual"><span id="rollover" class="rollover"></span><h3 id="result-title" tabindex="-1">乗車日時の計算結果</h3><div id="actual-date" class="actual-date"></div><div id="actual-time" class="actual-time"></div><p id="actual-clock"></p></div><div class="prep"><h3>乗車に向けて準備する目安</h3><p id="prep"></p><small>集合時刻や自宅を出る時刻の指定ではありません。移動時間を見込んで、予約元の集合時刻に合わせてください。</small></div><div id="schedule" class="schedule" hidden><h3>到着とホテルの予定</h3><dl><div id="arrival-row"><dt>バス到着</dt><dd id="arrival-summary"></dd></div><div id="hotel-row"><dt>チェックイン</dt><dd id="hotel-summary"></dd></div></dl><p id="gap" class="gap"></p><small>空室・荷物預かり・早めの入室の可否は、ホテルへご確認ください。</small></div><div class="warning"><strong>予約元で必ず最終確認</strong><div id="warnings"></div><p>乗車停留所の<strong>実際の日付・集合時刻・出発時刻・到着日</strong>を、予約確認メールや乗車券と照合してください。</p></div><button id="copy" class="copy" type="button">確認結果をコピー</button><button id="show-memo" class="text-button memo-button" type="button">確認メモを表示・選択</button><p id="copy-status" role="status"></p><div id="copy-fallback" hidden><label for="copy-text">確認メモ（選択して手動コピーできます）</label><textarea id="copy-text" readonly rows="12"></textarea></div></div></section></div>
<section class="tool-sharing" aria-labelledby="tool-share-title"><h2 id="tool-share-title">夜行バスに乗る人へ、このツールを。</h2><p id="tool-share-hint">サービス名・説明・URLだけを共有します。入力した乗車日・時刻・ホテルの予定は含みません。</p><button id="share-tool" class="copy" type="button" aria-describedby="tool-share-hint">このツールを共有</button><button id="show-tool-share" class="text-button" type="button" aria-controls="tool-share-fallback">紹介文を表示・選択</button><p id="tool-share-status" role="status" aria-live="polite" aria-atomic="true"></p><div id="tool-share-fallback" hidden><label for="tool-share-text">サイトの紹介文（選択して手動コピーできます）</label><textarea id="tool-share-text" readonly rows="6" spellcheck="false"></textarea></div></section>
<section class="reading"><p class="eyebrow">BEFORE YOU GO</p><h2>日付の境目は、この3つを確認。</h2><div class="guide-cards"><article><span class="guide-num">01</span><h3>24時は「翌日の0時」</h3><p>11月7日24:20は、カレンダーでは11月8日0:20。25:10なら翌日の1:10です。</p><a href="/guide.html#hours">24時・25時表記の読み方 →</a></article><article><span class="guide-num">02</span><h3>「運行日」と日付を分ける</h3><p>同じ深夜の便でも、予約サイトの検索日や運行日と、実際に乗る日付が一致するとは限りません。</p><a href="/guide.html#booking">予約日の注意点 →</a></article><article><span class="guide-num">03</span><h3>ホテルは到着時刻も確認</h3><p>朝のバス到着とホテルの入室開始は別。宿泊日・チェックイン予定を並べて確認しましょう。</p><a href="/guide.html#hotel">遠征・宿泊の日程の整え方 →</a></article></div></section>
<section class="sources"><h2>公式の案内も、あわせて確認。</h2><p>表記の扱いは予約元の最新案内を優先してください。以下の内容を参照して制作しました（確認日：2026年10月23日）。</p><div class="source-links"><a href="https://faq.willer.co.jp/s/article/1470">WILLER：24時を過ぎる出発 ↗</a><a href="https://www.489.fm/faq/reserve/p12.html">さくら高速バス：深夜便の予約 ↗</a><a href="https://www.milkyway-ex.com/news92">ミルキーウェイ：出発までの流れ ↗</a></div></section></main>'''
page('index.html','夜行バスの24時は何日？｜日付まちがい防止ナビ','夜行バスの24時・25時表記を実際のカレンダー日時に変換。到着とホテル予定の時間差も無料確認。日本時間対応・登録不要。',home,True)

def doc(title,body):return '<main id="main" class="document"><a class="back" href="/">← 日時チェックへ</a><h1>'+title+'</h1>'+body+'<p class="updated">更新・公式情報確認日：2026年10月23日</p></main>'
guide='''<p class="lead">夜行バスの「出発日」は、時計の0時で切り替わる日付と同じ意味とは限りません。まず表記を読み解き、最後にご自身の予約と照合しましょう。</p><nav class="toc" aria-label="目次"><a href="#hours">24時・25時とは</a><a href="#booking">予約日との違い</a><a href="#borders">月末・年越し</a><a href="#event">ライブ遠征</a><a href="#hotel">ホテルの予定</a><a href="#faq">よくある質問</a></nav>
<section id="hours"><h2>夜行バスの24時・25時表記とは</h2><p>24:00は翌日の00:00、24:30は翌日の00:30、25:00は翌日の01:00を表します。「7日の24時」は7日の夜が終わって8日に切り替わる瞬間です。8日の夜まで待つと、丸1日違います。</p><div class="table-wrap"><table><caption>2026年11月7日の表記を変換すると</caption><thead><tr><th>入力する表記</th><th>カレンダー上の日時（JST）</th></tr></thead><tbody><tr><td>11月7日 23:59</td><td>11月7日（土）午後11時59分</td></tr><tr><td>11月7日 24:00</td><td>11月8日（日）午前0時00分</td></tr><tr><td>11月7日 24:30</td><td>11月8日（日）午前0時30分</td></tr><tr><td>11月7日 25:00</td><td>11月8日（日）午前1時00分</td></tr></tbody></table></div><p>このツールは出発時刻00:00〜29:59に対応します。30:00や24:60を別の時刻へ直すことはせず、エラーを表示します。</p></section>
<section id="booking"><h2>予約日と、実際の乗車日の違い</h2><p>ここでいう「予約画面の出発日」は購入・決済した日ではありません。予約詳細や乗車券に書かれた出発日を確認してください。夜行便では、日付が変わった後の停留所でも、前日から始まる便として案内される場合があります。</p><p><a href="https://faq.willer.co.jp/s/article/1470">WILLER公式FAQ</a>は夜行便の検索・予約日を到着日の前日とし、12月31日25時の便には1月1日午前1時に乗る例を示しています。<a href="https://www.489.fm/faq/reserve/p12.html">さくら高速バス公式FAQ</a>も24時を過ぎる便について前日を選択し、最終画面の到着日を確認するよう案内しています。<a href="https://www.milkyway-ex.com/news92">ミルキーウェイ公式案内</a>でも夜行便の検索日を到着日の前日と説明しています。</p><div class="warning"><strong>この案内をすべての会社へ当てはめないでください。</strong><p>予約サイトによって日付の扱いや「翌日」の表示が異なります。11月7日00:20という入力は、このツールでは11月7日午前0時20分として計算しますが、便の運行日まで確定できません。「11月7日運行・翌日00:20」のような記載なら、予約元で実際の日時を確認してください。</p></div><p>出発地を途中の停留所に変更した場合も、自分の乗車停留所の日時を見直しましょう。始発地の日付だけで判断しないことが大切です。</p></section>
<section id="borders"><h2>月またぎ・年越しの具体例</h2><p>24時以降の変換では、日付だけでなく月・年も進むことがあります。</p><ul><li>2026年11月30日24:20 → 2026年12月1日午前0時20分</li><li>2026年12月31日24:15 → 2027年1月1日午前0時15分</li><li>2028年2月28日24:30 → 2028年2月29日午前0時30分（うるう年）</li><li>2027年2月28日24:30 → 2027年3月1日午前0時30分</li></ul><p>月末をまたぐ遠征では、バスとホテルを同じ月のカレンダーだけで見ないようにしましょう。このツールは日本時間で計算し、端末の海外時間設定に合わせた変換はしません。</p></section>
<section id="event"><h2>ライブ遠征では「行き」と「帰り」を別々に確認</h2><p>11月8日の朝に到着する予定で、予約画面が11月7日24:20発なら、準備する目安は7日の夜です。一方、8日のライブが終わった後の11月8日24:20発は、カレンダーでは9日午前0時20分です。行きと帰りで同じ「24:20」でも、乗車する日は異なります。</p><ol><li>公演日と開場・開演時刻を確認する。</li><li>行きの到着日と、公演会場までの移動時間を整理する。</li><li>帰りは公演の終了予定と、乗車場所・集合時刻を別に確認する。</li><li>行き・帰りそれぞれで日時を入力し、確認メモを残す。</li></ol><p>道路の混雑や公演の延長はこのツールでは予測しません。「予定上間に合う」ことと実際の到着保証は別です。</p></section>
<section id="hotel"><h2>到着日とホテルのチェックイン日を整理する</h2><p>11月8日7:00にバスが到着し、ホテルのチェックイン予定が同日15:00なら、時間差は8時間です。この8時間は予定の差であり、待機場所や早めに入室できることを保証する数字ではありません。</p><p>任意欄には、実際のカレンダー日付と00〜23時表記の時刻を入力してください。ホテルが「7日宿泊・チェックイン25時」のように案内している場合は、実際の入館予定が8日1時であるかホテルに確認し、日付・時刻を合わせて入力します。</p><p>チェックインがバス到着より前でも、前泊の部屋を確保しているなど意図した予約かもしれません。自動的に予約ミスとは判断しません。宿泊日、深夜到着時の連絡、荷物預かり、アーリーチェックインの可否は、施設ごとに確認してください。</p></section>
<section id="faq"><h2>よくある質問</h2><details><summary>この結果の日付でバスを予約すればよいですか？</summary><p>いいえ。結果は入力表記のカレンダー換算です。検索・予約に選ぶ日付や便の運行日は、予約サイトの案内に従ってください。</p></details><details><summary>0:20と24:20は同じですか？</summary><p>同じ入力日なら1日異なります。11月7日0:20は7日午前0時20分、11月7日24:20は8日午前0時20分です。ただし予約画面の「翌日」注記などは本ツールでは読み取れません。</p></details><details><summary>全角文字でも入力できますか？</summary><p>２０２６／１１／０７、２４：２０のような全角数字・区切り文字に対応します。年月日は「2026/11/07」、時刻は「24:20」の形にしてください。不正な日付や分は補正しません。</p></details><details><summary>入力した予定は保存・送信されますか？</summary><p>旅行予定をサーバーへ送信する機能や保存機能はありません。コピーした確認メモは端末のクリップボードに入ります。共有先はご自身で選んでください。</p></details><details><summary>確認結果をコピーできない場合は？</summary><p>ブラウザーの制限などで失敗した場合は、選択できる確認メモを表示します。「確認メモを表示・選択」から手動コピーすることもできます。</p></details><details><summary>海外のバスにも使えますか？</summary><p>日本国内の予定・日本時間（JST）専用です。海外の現地時間や夏時間には対応していません。</p></details></section>'''
page('guide.html','夜行バスの24時・25時と予約日の読み方｜日付まちがい防止ナビ','24時以降の乗車日、年越し・月末・ライブ遠征・ホテルの日程確認を具体例と公式案内で解説。',doc('出発前に知っておきたい、日付の読み方。',guide))
page('privacy.html','プライバシー｜日付まちがい防止ナビ','旅行予定の端末内処理、コピー機能、アクセス情報、広告について説明します。',doc('プライバシーについて','''<section><h2>入力した旅行予定</h2><p>日付・時刻の計算はブラウザー内で実行します。入力値をサーバーへ送る機能、会員登録、予約番号の入力、Cookieやローカルストレージへの予定保存は設けていません。URLにも予定を埋め込みません。</p></section><section><h2>確認メモと端末</h2><p>「コピー」を押すと確認結果が端末のクリップボードに保存されます。手動でコピー・共有した内容の取り扱いは、共有先のサービスにも従います。共用端末では利用後に入力を消し、クリップボードに予定が残ることに注意してください。ブラウザー自体の入力復元や履歴の挙動までは本サイトでは制御できません。</p></section><section><h2>サイトの配信・アクセス情報</h2><p>ホスティング事業者は、サイトの配信やセキュリティのためIPアドレス、アクセス日時などを取り扱う場合があります。これはフォームで入力した予定の送信とは別です。<a href="https://www.cloudflare.com/privacypolicy/">Cloudflareのプライバシーポリシー</a>もご確認ください。初版に独自のアクセス解析スクリプトは導入していません。</p></section><section><h2>広告について</h2><p>初版では広告配信スクリプトを読み込んでいません。Google AdSenseの所有権確認用メタタグとads.txtを準備していますが、それだけで広告の承認・配信・収益が発生するものではありません。</p><p>今後広告を導入する場合は、Cookie等の使用目的と第三者の情報取り扱いを本ページに追記し、対象地域で必要な同意管理を整備します。旅行予定を広告へ渡す仕組みは設けません。<a href="https://policies.google.com/technologies/ads?hl=ja">Googleの広告に関する説明</a></p></section><section><h2>外部リンク・お問い合わせ</h2><p>リンクを開いた後は移動先の方針が適用されます。不具合報告は<a href="/about.html#contact">運営・お問い合わせ</a>からお願いします。公開の報告欄には予約番号・氏名・連絡先・実際の旅行予定を書かないでください。</p></section>'''))
page('terms.html','利用上の注意｜日付まちがい防止ナビ','日時の計算範囲、予約内容を保証しないこと、公式情報の最終確認について。',doc('利用上の注意','''<section><h2>本サービスの役割</h2><p>入力した出発日の00:00〜29:59を日本時間のカレンダー日時へ換算する、無料の確認補助ツールです。予約代行・乗車券発行・運行情報の照会は行いません。運行会社や予約サイトの公式サービスではありません。</p></section><section><h2>予約元での確認が必要です</h2><p>計算結果が正しくても、入力の誤りや予約サイト固有の運行日・「翌日」表記を判定することはできません。乗車場所、集合時刻、出発日、到着日を必ず予約元で確認してください。不明な場合は予約元へお問い合わせください。</p></section><section><h2>対応範囲</h2><p>日本国内の予定・JST（UTC+9）を対象に、1900〜9998年の入力に対応します。到着・ホテル予定は00:00〜23:59で入力してください。実際の運行、所要時間、空室、荷物預かり、ホテルの入室可否は判定しません。準備する夜の表示は目安で、集合時刻や自宅の出発時刻を指定するものではありません。</p></section><section><h2>情報・不具合について</h2><p>説明の参照日を明記し、正確な計算を目指して検証していますが、すべての端末や将来の予約表記を保証するものではありません。不具合を発見した場合は、個人情報を含めず<a href="/about.html#contact">運営へ報告</a>してください。説明と予約元の案内が異なる場合は、予約元の最新案内を優先してください。</p></section>'''))
page('about.html','運営・お問い合わせ｜日付まちがい防止ナビ','F計画SPが提供する無料の夜行バス日時確認ツール。運営方針、不具合の報告窓口と公式の参照先。',doc('運営・お問い合わせ','''<p class="lead">深夜の「何日に乗る？」を、出発前に整理できる場所を。</p><section><h2>サービスについて</h2><dl class="about-list"><dt>サービス名</dt><dd>日付まちがい防止ナビ</dd><dt>運営</dt><dd>F計画SP</dd><dt>利用料金</dt><dd>完全無料・登録不要</dd><dt>対象</dt><dd>日本国内の夜行バス・遠征の予定確認</dd><dt>開発開始</dt><dd>2026年10月23日</dd></dl><p>日付の読み違いを減らすための独立した小さなツールです。運行会社と利用者の契約内容を確認・保証するサービスではありません。将来の広告収益で、無料の提供を続けることを目指しています。</p></section><section id="contact"><h2>不具合・ご意見の窓口</h2><p><a class="primary-link" href="https://github.com/MORRY1992/bus-date-navi/issues">GitHubで不具合・ご意見を報告する ↗</a></p><p>投稿にはGitHubアカウントが必要です。報告内容は公開されます。<strong>予約番号、氏名、メールアドレス、実際の旅行予定は書かないでください。</strong>例の日付へ置き換え、入力の形式・期待した結果・表示された結果・ブラウザー名をお知らせください。本サイトから自動で報告を送ることはありません。</p><p>予約変更、キャンセル、乗り場の問い合わせは対応できません。予約確認メールにある運行会社・予約元の窓口へご連絡ください。</p></section><section><h2>正確性への取り組み</h2><p>年末・月末・うるう年・不正入力の自動テストを用意しています。処理は端末のタイムゾーンに依存させず、日本時間として扱います。予約サイト固有の規則は、計算とは別に案内します。</p><p><a href="https://github.com/MORRY1992/bus-date-navi">ソースコードと検証記録を見る ↗</a></p></section>'''))
